(5737508, 834970, 30861, '<td valign="top">Very bad artifacting in the sky ruins this otherwise beguiling take on the topic for me.</td>', 'Very bad artifacting in the sky ruins this otherwise beguiling take on the topic for me.', '2009-11-23 00:49:00.000000', NULL, 1),
