(5738598, 834601, 43774, '<td valign="top">Not liking the HDR here.....the foreground has a flat look. The sky is the only thing I like about this photo, sorry.</td>', 'Not liking the HDR here.....the foreground has a flat look. The sky is the only thing I like about this photo, sorry.', '2009-11-23 17:29:17.000000', NULL, 1),
(5738604, 834190, 43774, '<td valign="top">Image looks tilted. It''s quite a surreal looking photo actually, did you use a filter? The mountains almost look fake but not in a bad way. In an interesting way.</td>', 'Image looks tilted. It''s quite a surreal looking photo actually, did you use a filter? The mountains almost look fake but not in a bad way. In an interesting way.', '2009-11-23 17:32:37.000000', NULL, 1),
(5738609, 835130, 80691, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2009-11-23 17:34:21.000000', NULL, 1),
(5738610, 834683, 80691, '<td valign="top">Lighting and color are excellent. Great composition. Best of the bunch!</td>', 'Lighting and color are excellent. Great composition. Best of the bunch!', '2009-11-23 17:34:57.000000', NULL, 1),
(5738611, 835111, 43774, '<td valign="top">What a beautiful scene, I don''t understand why you did not clone out the dust spots!!! It''s like ordering a gourmet meal at a very expensive restaurant and being presented with an exquisite entree on a dirty plate!!! This photo is beautiful with great colours, the mist and the mountains, it''s just wonderful. But then you see the dust spots.</td>', 'What a beautiful scene, I don''t understand why you did not clone out the dust spots!!! It''s like ordering a gourmet meal at a very expensive restaurant and being presented with an exquisite entree on a dirty plate!!! This photo is beautiful with great colours, the mist and the mountains, it''s just wonderful. But then you see the dust spots.', '2009-11-23 17:35:38.000000', NULL, 1),
(5738613, 834877, 43774, '<td valign="top">Wonderful viewpoint.....what a beautiful scene.</td>', 'Wonderful viewpoint.....what a beautiful scene.', '2009-11-23 17:35:57.000000', NULL, 1),
(5738614, 833993, 43774, '<td valign="top">Nice sky and reflection. Good composition. Good job.</td>', 'Nice sky and reflection. Good composition. Good job.', '2009-11-23 17:36:41.000000', NULL, 1),
(5738615, 835130, 43774, '<td valign="top">I like this.</td>', 'I like this.', '2009-11-23 17:36:44.000000', NULL, 1),
(5738616, 835093, 43774, '<td valign="top">Very clear and smooth, great perspective and colours.</td>', 'Very clear and smooth, great perspective and colours.', '2009-11-23 17:36:46.000000', NULL, 1),
(5738617, 834612, 43774, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2009-11-23 17:36:47.000000', NULL, 1),
(5738618, 835019, 43774, '<td valign="top">Good perspective. I really like the look of the corn more so than the sky.</td>', 'Good perspective. I really like the look of the corn more so than the sky.', '2009-11-23 17:36:49.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5738619, 834978, 43774, '<td valign="top">Nice perspective and scene.</td>', 'Nice perspective and scene.', '2009-11-23 17:36:50.000000', NULL, 1),
(5738620, 835018, 43774, '<td valign="top">Amazing sky! I like how the patterns of the clouds seem to be echoed in the patterns of the sand. Robert is this yours?</td>', 'Amazing sky! I like how the patterns of the clouds seem to be echoed in the patterns of the sand. Robert is this yours?', '2009-11-23 17:36:52.000000', NULL, 1),
(5738621, 835100, 43774, '<td valign="top">Nice reflections, I like the look of the water on the shore.</td>', 'Nice reflections, I like the look of the water on the shore.', '2009-11-23 17:36:53.000000', NULL, 1),
(5738622, 834958, 43774, '<td valign="top">Beautiful scene, I''d love to live near mountains.</td>', 'Beautiful scene, I''d love to live near mountains.', '2009-11-23 17:36:56.000000', NULL, 1),
(5738623, 835107, 43774, '<td valign="top">Oversaturated but for some reason it works here.</td>', 'Oversaturated but for some reason it works here.', '2009-11-23 17:36:57.000000', NULL, 1),
(5738624, 834927, 43774, '<td valign="top">Nice view, I like the waves on the shore.</td>', 'Nice view, I like the waves on the shore.', '2009-11-23 17:36:59.000000', NULL, 1),
(5738625, 834886, 80691, '<td valign="top">Lovely composition.</td>', 'Lovely composition.', '2009-11-23 17:37:29.000000', NULL, 1),
(5738629, 834855, 43774, '<td valign="top">Nice, but could use some improvements. Crop off a bit at the bottom, you can see some railing or something that is distracting. Either clean your sensor or clone out the dust spots, there is one right in the center of the sky. You''ve composed the photo well with foreground interest and the colours look pretty good. But those few flaws are hurting your photo.</td>', 'Nice, but could use some improvements. Crop off a bit at the bottom, you can see some railing or something that is distracting. Either clean your sensor or clone out the dust spots, there is one right in the center of the sky. You''ve composed the photo well with foreground interest and the colours look pretty good. But those few flaws are hurting your photo.', '2009-11-23 17:38:23.000000', NULL, 1),
(5738630, 834891, 43774, '<td valign="top">Nice bright colours but looks over sharpened.</td>', 'Nice bright colours but looks over sharpened.', '2009-11-23 17:38:29.000000', NULL, 1),
(5738631, 834881, 43774, '<td valign="top">I like the scene, it''s quite interesting and a bit mysterious. Good sky and light. It looks a bit over sharpened and maybe over saturated as well.</td>', 'I like the scene, it''s quite interesting and a bit mysterious. Good sky and light. It looks a bit over sharpened and maybe over saturated as well.', '2009-11-23 17:38:31.000000', NULL, 1),
(5738632, 835002, 43774, '<td valign="top">A nice scene but a bit over exposed and over sharpened as well.</td>', 'A nice scene but a bit over exposed and over sharpened as well.', '2009-11-23 17:38:33.000000', NULL, 1),
(5738633, 834854, 43774, '<td valign="top">A nice scene, good sky. A bit too contrasty, though, you''ve lost detail in the whites and blacks.</td>', 'A nice scene, good sky. A bit too contrasty, though, you''ve lost detail in the whites and blacks.', '2009-11-23 17:38:34.000000', NULL, 1),
(5738634, 834738, 43774, '<td valign="top">I like the mixture of elements.....green hill, rocky mountain, etc. Seems to be a bit too much sky and the horizon is too centered. Sky looks a bit noisy too.</td>', 'I like the mixture of elements.....green hill, rocky mountain, etc. Seems to be a bit too much sky and the horizon is too centered. Sky looks a bit noisy too.', '2009-11-23 17:38:36.000000', NULL, 1),
(5738694, 834623, 6667, '<td valign="top">Absolutely astonishing.  I see some people in the image, but how did you manage to keep them out of the center of the shot.  8 here BOL</td>', 'Absolutely astonishing.  I see some people in the image, but how did you manage to keep them out of the center of the shot.  8 here BOL', '2009-11-23 18:54:21.000000', NULL, 1),
(5738744, 835119, 103266, '<td valign="top">many worlds in one photo - well done</td>', 'many worlds in one photo - well done', '2009-11-23 19:55:07.000000', NULL, 1),
(5738836, 835082, 96751, '<td valign="top">This looks like an illustration in a fairy tale book.  Gorgeous colors and lighting.</td>', 'This looks like an illustration in a fairy tale book.  Gorgeous colors and lighting.', '2009-11-23 21:17:20.000000', NULL, 1),
(5738839, 834633, 96751, '<td valign="top">Love the rays, nice wide angle shot, although it looks a bit oversharpened.</td>', 'Love the rays, nice wide angle shot, although it looks a bit oversharpened.', '2009-11-23 21:18:05.000000', NULL, 1),
(5738842, 834998, 96751, '<td valign="top">Very grand, good use of wide angle.  The sky is killer, but I feel that everything has the same importance, which affects the depth to me.</td>', 'Very grand, good use of wide angle.  The sky is killer, but I feel that everything has the same importance, which affects the depth to me.', '2009-11-23 21:19:04.000000', NULL, 1),
(5738843, 835009, 96751, '<td valign="top">Very serene and beautiful, but the colors look a bit hazy and grayish.</td>', 'Very serene and beautiful, but the colors look a bit hazy and grayish.', '2009-11-23 21:19:39.000000', NULL, 1),
(5738845, 834125, 96751, '<td valign="top">Great sky.  I''m guessing this is HDR?  The willows look really odd.</td>', 'Great sky.  I''m guessing this is HDR?  The willows look really odd.', '2009-11-23 21:21:25.000000', NULL, 1),
(5738846, 834978, 96751, '<td valign="top">I like the landscape, but the manor and the fountain (?) are lacking in detail.</td>', 'I like the landscape, but the manor and the fountain (?) are lacking in detail.', '2009-11-23 21:22:06.000000', NULL, 1),
(5738849, 835056, 96751, '<td valign="top">Wow!  Great processing.  That band of red is very eye-catching, but just a tish overdone.</td>', 'Wow!  Great processing.  That band of red is very eye-catching, but just a tish overdone.', '2009-11-23 21:22:35.000000', NULL, 1),
(5738851, 835014, 96751, '<td valign="top">I love this.  There is a story here, not just a landscape.  Wonderful detail on the rocks, lovely colors and lighting.  Great job.</td>', 'I love this.  There is a story here, not just a landscape.  Wonderful detail on the rocks, lovely colors and lighting.  Great job.', '2009-11-23 21:23:06.000000', NULL, 1),
(5738855, 834312, 96751, '<td valign="top">You really hit the peak of autumn.</td>', 'You really hit the peak of autumn.', '2009-11-23 21:23:55.000000', NULL, 1),
(5738857, 834877, 96751, '<td valign="top">How fabulous.  Reminds me of my visit to the Cotswolds this summer.  Beautiful scenery, but the shot looks a little foreshortened, and I think the church tower could have been made to pop a little more, or at least remove the green cast on it.</td>', 'How fabulous.  Reminds me of my visit to the Cotswolds this summer.  Beautiful scenery, but the shot looks a little foreshortened, and I think the church tower could have been made to pop a little more, or at least remove the green cast on it.', '2009-11-23 21:25:18.000000', NULL, 1),
(5738858, 834676, 96751, '<td valign="top">Great blues, nice shapes.  Just a little flat.</td>', 'Great blues, nice shapes.  Just a little flat.', '2009-11-23 21:25:49.000000', NULL, 1),
(5738860, 835098, 96751, '<td valign="top">Fabulous conversion.  What IS that thing?!</td>', 'Fabulous conversion.  What IS that thing?!', '2009-11-23 21:26:23.000000', NULL, 1),
(5738867, 834970, 96751, '<td valign="top">That sun spot really makes this shot.</td>', 'That sun spot really makes this shot.', '2009-11-23 21:26:56.000000', NULL, 1),
(5738870, 834756, 96751, '<td valign="top">Very Rembrandt!  Just a bit too centered for my taste.  And some sort of border would have really put a button on this.</td>', 'Very Rembrandt!  Just a bit too centered for my taste.  And some sort of border would have really put a button on this.', '2009-11-23 21:27:33.000000', NULL, 1),
(5738880, 834609, 96751, '<td valign="top">Gorgeous.  But really not liking the border.  It draws my eye away from the scene and looks like a mistake.</td>', 'Gorgeous.  But really not liking the border.  It draws my eye away from the scene and looks like a mistake.', '2009-11-23 21:29:31.000000', NULL, 1),
(5738881, 835000, 96751, '<td valign="top">Great content, but a bit overblown in the sunlit areas.</td>', 'Great content, but a bit overblown in the sunlit areas.', '2009-11-23 21:29:36.000000', NULL, 1),
(5738882, 834684, 96751, '<td valign="top">Very evocative image.  Love it.  Wish the ruts weren''t so straight-on.</td>', 'Very evocative image.  Love it.  Wish the ruts weren''t so straight-on.', '2009-11-23 21:30:09.000000', NULL, 1),
(5738884, 833993, 96751, '<td valign="top">Incredible reflection!</td>', 'Incredible reflection!', '2009-11-23 21:31:17.000000', NULL, 1),
(5738885, 835038, 96751, '<td valign="top">I love the color of the sky, but the content and composition is a bit weak.</td>', 'I love the color of the sky, but the content and composition is a bit weak.', '2009-11-23 21:31:50.000000', NULL, 1),
(5738886, 834615, 96751, '<td valign="top">I think a more rectangular crop would have made this shot even better.</td>', 'I think a more rectangular crop would have made this shot even better.', '2009-11-23 21:32:32.000000', NULL, 1),
(5738888, 834882, 96751, '<td valign="top">Very interesting picture.  Really feels like a bad dream.  Don''t know that it''s really a landscape, but I like the processing on this.</td>', 'Very interesting picture.  Really feels like a bad dream.  Don''t know that it''s really a landscape, but I like the processing on this.', '2009-11-23 21:33:25.000000', NULL, 1),
(5738890, 834854, 96751, '<td valign="top">Great sense of depth, love the water and mountains; the foreground looks odd to me.</td>', 'Great sense of depth, love the water and mountains; the foreground looks odd to me.', '2009-11-23 21:34:17.000000', NULL, 1),
(5738891, 835019, 96751, '<td valign="top">This doesn''t look focused to me...but it might be my eyes :-)</td>', 'This doesn''t look focused to me...but it might be my eyes :-)', '2009-11-23 21:34:45.000000', NULL, 1),
(5738897, 834992, 96751, '<td valign="top">This has to be in the Cotswolds.  Gorgeous.  Love the late lighting - especially along the golden grass on the left.</td>', 'This has to be in the Cotswolds.  Gorgeous.  Love the late lighting - especially along the golden grass on the left.', '2009-11-23 21:36:42.000000', NULL, 1),
(5738898, 834927, 96751, '<td valign="top">Nice, crisp shot.</td>', 'Nice, crisp shot.', '2009-11-23 21:36:58.000000', NULL, 1),
(5738900, 834852, 96751, '<td valign="top">Beautiful.  I might have cropped the darker foreground a little tighter - it feels like it''s blocking the view rather than framing it.</td>', 'Beautiful.  I might have cropped the darker foreground a little tighter - it feels like it''s blocking the view rather than framing it.', '2009-11-23 21:38:00.000000', NULL, 1),
(5738903, 834974, 96751, '<td valign="top">This looks like a painting!</td>', 'This looks like a painting!', '2009-11-23 21:38:29.000000', NULL, 1),
(5738908, 834221, 96751, '<td valign="top">I love this.  Stunning, delicate, moody, a real dreamscape.</td>', 'I love this.  Stunning, delicate, moody, a real dreamscape.', '2009-11-23 21:40:25.000000', NULL, 1),
(5738910, 835130, 96751, '<td valign="top">Majestic, although the ridge on the left sort of blends into the sky.</td>', 'Majestic, although the ridge on the left sort of blends into the sky.', '2009-11-23 21:41:11.000000', NULL, 1),
(5738913, 835093, 96751, '<td valign="top">Wonderful twilight colors.  Undecided about the heaviness of the bridge element in the foreground.</td>', 'Wonderful twilight colors.  Undecided about the heaviness of the bridge element in the foreground.', '2009-11-23 21:42:23.000000', NULL, 1),
(5738915, 835078, 96751, '<td valign="top">Love the transparency of the water, the light on the stumps, and the fact that they look like ducks swimming down(?)stream.  The light on the water is luminous.  Also, not sure white is the right color for the border.</td>', 'Love the transparency of the water, the light on the stumps, and the fact that they look like ducks swimming down(?)stream.  The light on the water is luminous.  Also, not sure white is the right color for the border.', '2009-11-23 21:43:22.000000', NULL, 1),
(5738922, 834928, 96751, '<td valign="top">Great tones!  I know why you included the contrail, but I think the crop is more powerful just below it, to still include the trapezoid cloud...</td>', 'Great tones!  I know why you included the contrail, but I think the crop is more powerful just below it, to still include the trapezoid cloud...', '2009-11-23 21:45:20.000000', NULL, 1),
(5738923, 835059, 37845, '<td valign="top">Ive been to Niagara many times, but have never come away with a shot that I was satisfied with. I think your shot is really strong, as the mist doesnt obscure the falls too much, and your processing leaves an intense mood overall. Nice shot. 8</td>', 'Ive been to Niagara many times, but have never come away with a shot that I was satisfied with. I think your shot is really strong, as the mist doesnt obscure the falls too much, and your processing leaves an intense mood overall. Nice shot. 8', '2009-11-23 21:45:42.000000', NULL, 1),
(5738924, 835019, 37845, '<td valign="top">It takes a keen eye, and great skill to make a dead cornfield look appealing. Great shot. 9</td>', 'It takes a keen eye, and great skill to make a dead cornfield look appealing. Great shot. 9', '2009-11-23 21:45:47.000000', NULL, 1),
(5738925, 834684, 37845, '<td valign="top">A landscape with an undefined horizon... this is perfect. For a landscape it contains a lot of emotion, and is processed beautifully.</td>', 'A landscape with an undefined horizon... this is perfect. For a landscape it contains a lot of emotion, and is processed beautifully.', '2009-11-23 21:45:51.000000', NULL, 1),
(5738926, 835093, 37845, '<td valign="top">I was just there a few weeks ago for the symmetry challenge. I never would have pictured getting this kind of colour out of the shot. Beautifully processed, I love how the bridge takes your eyes to the edge of the frame.</td>', 'I was just there a few weeks ago for the symmetry challenge. I never would have pictured getting this kind of colour out of the shot. Beautifully processed, I love how the bridge takes your eyes to the edge of the frame.', '2009-11-23 21:45:58.000000', NULL, 1),
(5738962, 835111, 30049, '<td valign="top">Darn sensor dust anyway!  :-)  I like the colors and layers you have captured here.  Good luck.</td>', 'Darn sensor dust anyway!  :-)  I like the colors and layers you have captured here.  Good luck.', '2009-11-23 22:13:16.000000', NULL, 1),
(5738986, 834955, 37444, '<td valign="top">Lovely and I like the vignetting. 8</td>', 'Lovely and I like the vignetting. 8', '2009-11-23 22:26:53.000000', NULL, 1),
(5738990, 834125, 37444, '<td valign="top">You cannot go wrong with sunset and water reflections :) 9</td>', 'You cannot go wrong with sunset and water reflections :) 9', '2009-11-23 22:27:48.000000', NULL, 1),
(5738991, 834996, 37444, '<td valign="top">Lovely but a bit too much HDR</td>', 'Lovely but a bit too much HDR', '2009-11-23 22:28:12.000000', NULL, 1),
(5738992, 834958, 37444, '<td valign="top">really gorgeous 8</td>', 'really gorgeous 8', '2009-11-23 22:28:28.000000', NULL, 1),
(5738995, 835019, 37444, '<td valign="top">Such an emotional image. Gorgeous HDR of a place of sadness. 9</td>', 'Such an emotional image. Gorgeous HDR of a place of sadness. 9', '2009-11-23 22:29:34.000000', NULL, 1),
(5738997, 835018, 37444, '<td valign="top">Love the way the land echoes the sky. 10</td>', 'Love the way the land echoes the sky. 10', '2009-11-23 22:30:05.000000', NULL, 1),
(5738998, 835000, 37444, '<td valign="top">Fantastic bridge! 7</td>', 'Fantastic bridge! 7', '2009-11-23 22:30:27.000000', NULL, 1),
(5739001, 835005, 37444, '<td valign="top">love the tones here. 7</td>', 'love the tones here. 7', '2009-11-23 22:30:58.000000', NULL, 1),
(5739009, 835011, 37444, '<td valign="top">It''s a lovely image. Too bad the sun washed out the sky. 7</td>', 'It''s a lovely image. Too bad the sun washed out the sky. 7', '2009-11-23 22:32:37.000000', NULL, 1),
(5739011, 835125, 37444, '<td valign="top">Nice change from all the rural scenes. 8</td>', 'Nice change from all the rural scenes. 8', '2009-11-23 22:33:28.000000', NULL, 1),
(5739012, 834190, 37444, '<td valign="top">Interesting PP 8</td>', 'Interesting PP 8', '2009-11-23 22:34:00.000000', NULL, 1),
(5739015, 835094, 37444, '<td valign="top">Well, I would not tag this as a landscape; more of an abstract. A very nice abstract. 8</td>', 'Well, I would not tag this as a landscape; more of an abstract. A very nice abstract. 8', '2009-11-23 22:34:34.000000', NULL, 1),
(5739016, 834881, 37444, '<td valign="top">Who knew tapioca came from a plantation? 8</td>', 'Who knew tapioca came from a plantation? 8', '2009-11-23 22:35:38.000000', NULL, 1),
(5739018, 834998, 37444, '<td valign="top">Love the details in the rocks 9</td>', 'Love the details in the rocks 9', '2009-11-23 22:36:43.000000', NULL, 1),
(5739019, 835051, 37444, '<td valign="top">I know it''s red rock country, but seems a bit too saturated. 7</td>', 'I know it''s red rock country, but seems a bit too saturated. 7', '2009-11-23 22:37:31.000000', NULL, 1),
(5739020, 835095, 37444, '<td valign="top">lovely park setting 7</td>', 'lovely park setting 7', '2009-11-23 22:37:55.000000', NULL, 1),
(5739021, 835084, 37444, '<td valign="top">Reminds me of the Sandias :) 8</td>', 'Reminds me of the Sandias :) 8', '2009-11-23 22:38:30.000000', NULL, 1),
(5739022, 834612, 37444, '<td valign="top">Now this is truly lovely and worthy of a 10.</td>', 'Now this is truly lovely and worthy of a 10.', '2009-11-23 22:39:08.000000', NULL, 1),
(5739024, 835087, 37444, '<td valign="top">Where did you shoot this from? Just wondering :) 7</td>', 'Where did you shoot this from? Just wondering :) 7', '2009-11-23 22:39:52.000000', NULL, 1),
(5739025, 834994, 37444, '<td valign="top">Very nicely done 9</td>', 'Very nicely done 9', '2009-11-23 22:40:23.000000', NULL, 1),
(5739026, 834554, 37444, '<td valign="top">Nice subject - 8</td>', 'Nice subject - 8', '2009-11-23 22:40:36.000000', NULL, 1),
