(5739030, 835059, 37444, '<td valign="top">Nicely done 8</td>', 'Nicely done 8', '2009-11-23 22:44:18.000000', NULL, 1),
(5739032, 835014, 37444, '<td valign="top">Most HDRs just don''t do anything for me, but this is gorgeous! 9</td>', 'Most HDRs just don''t do anything for me, but this is gorgeous! 9', '2009-11-23 22:45:42.000000', NULL, 1),
