(5739035, 835107, 37444, '<td valign="top">Oh yeah, that''s my kind of landscape. 10</td>', 'Oh yeah, that''s my kind of landscape. 10', '2009-11-23 22:49:58.000000', NULL, 1),
(5739036, 835074, 37444, '<td valign="top">Just lovely; the colors soothe; the subject intrigues. 10</td>', 'Just lovely; the colors soothe; the subject intrigues. 10', '2009-11-23 22:50:59.000000', NULL, 1),
