(5739177, 834996, 21714, '<td valign="top">Quite different and like the weird sense of scale it presents.</td>', 'Quite different and like the weird sense of scale it presents.', '2009-11-24 02:29:18.000000', NULL, 1),
(5739209, 835059, 102386, '<td valign="top">Lovely mood captured here. Strong composition and processing. I always find it a challenge to decide upon the amount of blown whites in rushing water. For me the balance here is picture perfect. I will come back to this and use it as reference for my own work :) I expect this to be on the front page (no vote)</td>', 'Lovely mood captured here. Strong composition and processing. I always find it a challenge to decide upon the amount of blown whites in rushing water. For me the balance here is picture perfect. I will come back to this and use it as reference for my own work :) I expect this to be on the front page (no vote)', '2009-11-24 06:22:02.000000', NULL, 1),
