INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5739879, 834928, 51538, '<td valign="top">I like the natural not over processed look of your photo.  Nice view. 10</td>', 'I like the natural not over processed look of your photo.  Nice view. 10', '2009-11-24 13:54:54.000000', NULL, 1),
(5739880, 834756, 51538, '<td valign="top">One of the few in which soft focus enhances.  Nice work.</td>', 'One of the few in which soft focus enhances.  Nice work.', '2009-11-24 13:54:58.000000', NULL, 1),
(5739881, 834125, 51538, '<td valign="top">I''m glad this has not been given the HDR treatment.  So much nicer for shadows and silhouettes.</td>', 'I''m glad this has not been given the HDR treatment.  So much nicer for shadows and silhouettes.', '2009-11-24 13:55:23.000000', NULL, 1),
