(5740109, 834665, 60047, '<td valign="top">Love the colors in the center. Almost too much darkness included on the sides.</td>', 'Love the colors in the center. Almost too much darkness included on the sides.', '2009-11-24 17:02:28.000000', NULL, 1),
(5740113, 834908, 60047, '<td valign="top">Almost too much of the dark. I do like the colors at the horizon.</td>', 'Almost too much of the dark. I do like the colors at the horizon.', '2009-11-24 17:04:17.000000', NULL, 1),
