(5740332, 835006, 60047, '<td valign="top">Heavy on the mid-tones in this B&amp;W. Nice peaceful and serene mood evoked here.</td>', 'Heavy on the mid-tones in this B&W. Nice peaceful and serene mood evoked here.', '2009-11-24 20:04:02.000000', NULL, 1),
