(5740353, 835121, 60047, '<td valign="top">I like the balance of the foreground vs BG. Nice clarity.</td>', 'I like the balance of the foreground vs BG. Nice clarity.', '2009-11-24 20:16:18.000000', NULL, 1),
(5740361, 834854, 60047, '<td valign="top">Great shot. Neat sky. Nice textures in the grass. Top left corner very dark vs the rest of the shot.</td>', 'Great shot. Neat sky. Nice textures in the grass. Top left corner very dark vs the rest of the shot.', '2009-11-24 20:19:17.000000', NULL, 1),
