(5740536, 835001, 60047, '<td valign="top">Very pretty, peaceful and serene.</td>', 'Very pretty, peaceful and serene.', '2009-11-24 22:11:47.000000', NULL, 1),
(5740537, 834721, 42013, '<td valign="top">mae? ;) I am personally a fan of blown out sun spots/rays. In order for this to score well, it is probably necessary to find some detail/tones in the mountains from near to far. I can see a little bit, but not quite enough to give the correct amount of detail in the shadow areas. IMO of course. :)</td>', 'mae? ;) I am personally a fan of blown out sun spots/rays. In order for this to score well, it is probably necessary to find some detail/tones in the mountains from near to far. I can see a little bit, but not quite enough to give the correct amount of detail in the shadow areas. IMO of course. :)', '2009-11-24 22:12:01.000000', NULL, 1),
(5740538, 834601, 60047, '<td valign="top">Well done. Nice colors and light balance between the sunset and the land.</td>', 'Well done. Nice colors and light balance between the sunset and the land.', '2009-11-24 22:12:43.000000', NULL, 1),
(5740540, 834668, 60047, '<td valign="top">I wish the shot was just a bit more crisp and sharp.</td>', 'I wish the shot was just a bit more crisp and sharp.', '2009-11-24 22:13:14.000000', NULL, 1),
(5740542, 834881, 60047, '<td valign="top">Very dramatic sky. The boost on the green is just a tad too much for my taste.</td>', 'Very dramatic sky. The boost on the green is just a tad too much for my taste.', '2009-11-24 22:14:11.000000', NULL, 1),
(5740543, 834985, 60047, '<td valign="top">Nice high key answer to the challenge.</td>', 'Nice high key answer to the challenge.', '2009-11-24 22:14:33.000000', NULL, 1),
(5740545, 834312, 60047, '<td valign="top">I love the lines of the bridge. I like how the orange of the tree is complimented by the blue of the bridge.</td>', 'I love the lines of the bridge. I like how the orange of the tree is complimented by the blue of the bridge.', '2009-11-24 22:15:34.000000', NULL, 1),
