(5740556, 835130, 60047, '<td valign="top">A great capture. Nice light. Nice colors.</td>', 'A great capture. Nice light. Nice colors.', '2009-11-24 22:18:29.000000', NULL, 1),
(5740557, 834377, 60047, '<td valign="top">Great detail &amp; DOF.</td>', 'Great detail & DOF.', '2009-11-24 22:18:32.000000', NULL, 1),
(5740558, 835059, 60047, '<td valign="top">What a great fresh capture of a well known site. Nice water.</td>', 'What a great fresh capture of a well known site. Nice water.', '2009-11-24 22:18:38.000000', NULL, 1),
(5740559, 834743, 60047, '<td valign="top">Great visual statement underscored by the title. Great decision on the use of B &amp; W. A good photojournalist shot.</td>', 'Great visual statement underscored by the title. Great decision on the use of B & W. A good photojournalist shot.', '2009-11-24 22:18:45.000000', NULL, 1),
