(5740561, 834716, 60047, '<td valign="top">Great colors &amp; textures, here.</td>', 'Great colors & textures, here.', '2009-11-24 22:18:48.000000', NULL, 1),
(5740562, 835013, 60047, '<td valign="top">Wow. Great deep blues and wonderful complimentary golden browns. Nice work.</td>', 'Wow. Great deep blues and wonderful complimentary golden browns. Nice work.', '2009-11-24 22:18:50.000000', NULL, 1),
(5740563, 834732, 60047, '<td valign="top">Quite a fascinating shot. Wonderful textures.</td>', 'Quite a fascinating shot. Wonderful textures.', '2009-11-24 22:18:52.000000', NULL, 1),
