(5740569, 834928, 60047, '<td valign="top">I really like the hills in the mist.</td>', 'I really like the hills in the mist.', '2009-11-24 22:19:25.000000', NULL, 1),
(5740570, 834996, 60047, '<td valign="top">Wonderful detail.</td>', 'Wonderful detail.', '2009-11-24 22:19:27.000000', NULL, 1),
(5740571, 834721, 60047, '<td valign="top">Awesome blues. Great framing.</td>', 'Awesome blues. Great framing.', '2009-11-24 22:19:29.000000', NULL, 1),
(5740572, 834955, 60047, '<td valign="top">I really like the way you''ve captured the beauty of the bare trees. The lawn in the foreground really helps frame this subject nicely. Great concept and execution.</td>', 'I really like the way you''ve captured the beauty of the bare trees. The lawn in the foreground really helps frame this subject nicely. Great concept and execution.', '2009-11-24 22:19:32.000000', NULL, 1),
(5740573, 835003, 60047, '<td valign="top">I love the texture of the rock. I really like the colors on the bottom vs the top. I am not a fan of the centering of the rock and sun.</td>', 'I love the texture of the rock. I really like the colors on the bottom vs the top. I am not a fan of the centering of the rock and sun.', '2009-11-24 22:19:34.000000', NULL, 1),
(5740575, 834676, 60047, '<td valign="top">A classic composition composed and executed very well.</td>', 'A classic composition composed and executed very well.', '2009-11-24 22:19:40.000000', NULL, 1),
(5740576, 834633, 60047, '<td valign="top">Very nicely done.</td>', 'Very nicely done.', '2009-11-24 22:19:42.000000', NULL, 1),
(5740577, 834609, 60047, '<td valign="top">This is a great capture. The colors in the trees are great. The clouds in the hills are dramatic. I realize you are probably on a slope and, therefore, the shot is level, but the slope of the ground at the bottom of the pic is distracting. I''ll bet you could artificially "level" this by tilting the crop and it might appear to be more level. Great work.</td>', 'This is a great capture. The colors in the trees are great. The clouds in the hills are dramatic. I realize you are probably on a slope and, therefore, the shot is level, but the slope of the ground at the bottom of the pic is distracting. I''ll bet you could artificially "level" this by tilting the crop and it might appear to be more level. Great work.', '2009-11-24 22:20:08.000000', NULL, 1),
(5740578, 834648, 60047, '<td valign="top">Beautiful. Love the contrast in colors and textures.</td>', 'Beautiful. Love the contrast in colors and textures.', '2009-11-24 22:20:12.000000', NULL, 1),
(5740579, 834971, 60047, '<td valign="top">Beautiful water. Great color tones.</td>', 'Beautiful water. Great color tones.', '2009-11-24 22:20:16.000000', NULL, 1),
(5740580, 834827, 60047, '<td valign="top">Very interesting capture. I like the heavy contrast.</td>', 'Very interesting capture. I like the heavy contrast.', '2009-11-24 22:20:18.000000', NULL, 1);
