(5743733, 835083, 40355, '<td valign="top">I really like this shot - the texture in the image is great, it gives it a real moody feel, and the moon and its smeared trail really show something different from the rest of the images in the challenge.  Combined with the title, it''s really cool!</td>', 'I really like this shot - the texture in the image is great, it gives it a real moody feel, and the moon and its smeared trail really show something different from the rest of the images in the challenge.  Combined with the title, it''s really cool!', '2009-11-27 11:49:31.000000', NULL, 1),
(5743768, 834579, 44611, '<td valign="top">I love the way the path disappears innto the pink mist and the overhanging fir tree.  I wish though that there was a little more of interest in the foreground, it just seems very dark.</td>', 'I love the way the path disappears innto the pink mist and the overhanging fir tree.  I wish though that there was a little more of interest in the foreground, it just seems very dark.', '2009-11-27 12:05:19.000000', NULL, 1),
