(5743789, 834648, 44611, '<td valign="top">Stunningly beautiful.  Great colour and detail.  Surely unusual to get a sky like that in the desert.</td>', 'Stunningly beautiful.  Great colour and detail.  Surely unusual to get a sky like that in the desert.', '2009-11-27 12:18:14.000000', NULL, 1),
(5743795, 835008, 44611, '<td valign="top">Such a shame the foreground buildings are cropped in this.  I would have cropped out the tree on the right and probably the left to concentrate the eye a bit more on the horizon and that sky.</td>', 'Such a shame the foreground buildings are cropped in this.  I would have cropped out the tree on the right and probably the left to concentrate the eye a bit more on the horizon and that sky.', '2009-11-27 12:19:54.000000', NULL, 1),
