(5744396, 835014, 62357, '<td valign="top">This is stunning. Beautifully processed. Well done.</td>', 'This is stunning. Beautifully processed. Well done.', '2009-11-28 01:12:36.000000', NULL, 1),
(5744397, 835083, 62357, '<td valign="top">Like your title.  Gorgeous colours.</td>', 'Like your title.  Gorgeous colours.', '2009-11-28 01:12:40.000000', NULL, 1),
