(5744399, 834555, 62357, '<td valign="top">Like this very much.</td>', 'Like this very much.', '2009-11-28 01:15:31.000000', NULL, 1),
(5744400, 835130, 62357, '<td valign="top">Early season snow looks so fresh.  Beautiful.</td>', 'Early season snow looks so fresh.  Beautiful.', '2009-11-28 01:15:34.000000', NULL, 1),
(5744401, 834907, 62357, '<td valign="top">Gorgeous, although I hate even to say this but the tree/bush is somewhat disturbing me.  I know foreground interest is good and all that, but in this case it''s not working for me. Still a beautiful image.  The nitpicky stuff comes from spending too much time on DPC! 7</td>', 'Gorgeous, although I hate even to say this but the tree/bush is somewhat disturbing me.  I know foreground interest is good and all that, but in this case it''s not working for me. Still a beautiful image.  The nitpicky stuff comes from spending too much time on DPC! 7', '2009-11-28 01:16:24.000000', NULL, 1),
(5744402, 834955, 62357, '<td valign="top">Lovely B&amp;W.</td>', 'Lovely B&W.', '2009-11-28 01:16:38.000000', NULL, 1),
(5744413, 835018, 42013, '<td valign="top">Lovely light Penny <strike>Robert</strike>! patterns, angles, and framing--has it all. 8<br/><br/><i>Message edited by author 2009-12-01 01:14:56.</i></td>', 'Lovely light Penny Robert! patterns, angles, and framing--has it all. 8', '2009-11-28 01:46:35.000000', '2009-12-01 01:14:56.000000', 1),
(5744416, 834684, 83313, '<td valign="top"><strike>This screams <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=50695" rel="nofollow" target="_blank">Posthumous</a> to me. If it is not his entry, I would expect him to like this one.</strike> <br/> <br/>Upon a second look, it''s probably not his after all. Not blurry enough for his usual style.</td>', 'This screams  Posthumous to me. If it is not his entry, I would expect him to like this one.  Upon a second look, it''s probably not his after all. Not blurry enough for his usual style.', '2009-11-28 02:25:21.000000', NULL, 1),
(5744490, 835044, 106349, '<td valign="top">Honestly, I think there is not enough contrast in this shot; not sure if it''s because it''s b&amp;w.</td>', 'Honestly, I think there is not enough contrast in this shot; not sure if it''s because it''s b&w.', '2009-11-28 07:38:34.000000', NULL, 1),
(5744491, 835035, 7810, '<td valign="top">I like the simple composition Well shot</td>', 'I like the simple composition Well shot', '2009-11-28 07:40:16.000000', NULL, 1),
(5744492, 835007, 7810, '<td valign="top">Your models help to emphasize the long DOF. Nicely done.<br/>I like the framing elements as well</td>', 'Your models help to emphasize the long DOF. Nicely done.I like the framing elements as well', '2009-11-28 07:42:12.000000', NULL, 1),
(5744493, 835054, 7810, '<td valign="top">A nice chilly scene. I like the tones and colours</td>', 'A nice chilly scene. I like the tones and colours', '2009-11-28 07:42:51.000000', NULL, 1),
(5744494, 835011, 7810, '<td valign="top">Interesting  composition. I like the lines in the shot</td>', 'Interesting  composition. I like the lines in the shot', '2009-11-28 07:43:25.000000', NULL, 1),
(5744495, 834705, 7810, '<td valign="top">This is a beautiful scene. Great for the landscape challenge. You should remember this location and reshoot with models. A lone figure walking towards the camera, a couple in a loving embrace, You know , something to hold the viewer in the shot(my 2 cents)</td>', 'This is a beautiful scene. Great for the landscape challenge. You should remember this location and reshoot with models. A lone figure walking towards the camera, a couple in a loving embrace, You know , something to hold the viewer in the shot(my 2 cents)', '2009-11-28 07:46:43.000000', NULL, 1),
(5744496, 835037, 7810, '<td valign="top">Interesting  image , shot well</td>', 'Interesting  image , shot well', '2009-11-28 07:47:15.000000', NULL, 1),
(5744497, 834190, 7810, '<td valign="top">Ah! I love the lone tree. This is a nice scene, a strong image. I like the texture and detail in the tree</td>', 'Ah! I love the lone tree. This is a nice scene, a strong image. I like the texture and detail in the tree', '2009-11-28 07:48:51.000000', NULL, 1),
(5744498, 834566, 7810, '<td valign="top">Great effect on the water. Nice work with the slow shutter</td>', 'Great effect on the water. Nice work with the slow shutter', '2009-11-28 07:49:31.000000', NULL, 1),
(5744499, 835092, 106349, '<td valign="top">For a landscape, I generally like to see a pretty deep DOF.</td>', 'For a landscape, I generally like to see a pretty deep DOF.', '2009-11-28 07:50:24.000000', NULL, 1),
(5744500, 834852, 7810, '<td valign="top">A nice scene, however, the foreground is too dark and lacks detail</td>', 'A nice scene, however, the foreground is too dark and lacks detail', '2009-11-28 07:50:27.000000', NULL, 1),
(5744501, 834996, 106349, '<td valign="top">Beautiful location &amp; great composition.</td>', 'Beautiful location & great composition.', '2009-11-28 07:50:49.000000', NULL, 1),
(5744502, 834998, 7810, '<td valign="top">This is a wonderful scene. Great sky great textures in the rock. I love the solitude of the gnarly old building<br/>Nice composition</td>', 'This is a wonderful scene. Great sky great textures in the rock. I love the solitude of the gnarly old buildingNice composition', '2009-11-28 07:51:42.000000', NULL, 1),
