(5744504, 835008, 7810, '<td valign="top">This is an awesome scene. I wish the buildings on the bottom were not cut off. A re-crop would help this image</td>', 'This is an awesome scene. I wish the buildings on the bottom were not cut off. A re-crop would help this image', '2009-11-28 07:54:22.000000', NULL, 1),
(5744505, 835121, 7810, '<td valign="top">Nice scene. A good study for the challenge. Great lighting</td>', 'Nice scene. A good study for the challenge. Great lighting', '2009-11-28 07:54:54.000000', NULL, 1),
(5744506, 834601, 106349, '<td valign="top">I''d like to see a little more contrast in this shot. The sky looks beautiful but the foreground (1/2 of the shot) is slightly plain.</td>', 'I''d like to see a little more contrast in this shot. The sky looks beautiful but the foreground (1/2 of the shot) is slightly plain.', '2009-11-28 07:55:01.000000', NULL, 1),
(5744507, 835021, 106349, '<td valign="top">Great color!</td>', 'Great color!', '2009-11-28 07:55:30.000000', NULL, 1),
