(5744526, 834648, 106349, '<td valign="top">Great shot... one of my favorites.</td>', 'Great shot... one of my favorites.', '2009-11-28 08:51:22.000000', NULL, 1),
(5744527, 835111, 106349, '<td valign="top">Outstanding colors.</td>', 'Outstanding colors.', '2009-11-28 08:52:50.000000', NULL, 1),
