(5744796, 834877, 14867, '<td valign="top">Not the most spectacular of this challenge, but a simple and convincing image, very carefully composed, and standing out by its almost monochromatic elegance.<br/>One of my preferred.</td>', 'Not the most spectacular of this challenge, but a simple and convincing image, very carefully composed, and standing out by its almost monochromatic elegance.One of my preferred.', '2009-11-28 17:35:15.000000', NULL, 1),
(5744797, 834612, 14867, '<td valign="top">I''m not a big fan of your heavy black frame. The rest is amazing.</td>', 'I''m not a big fan of your heavy black frame. The rest is amazing.', '2009-11-28 17:37:46.000000', NULL, 1),
(5744800, 834221, 14867, '<td valign="top">Interesting and rather good attempt to make something different. Great mood, excellent muted colors, not sure of the composition though.</td>', 'Interesting and rather good attempt to make something different. Great mood, excellent muted colors, not sure of the composition though.', '2009-11-28 17:39:34.000000', NULL, 1),
