(5744881, 834854, 36808, '<td valign="top">I feel like I''m right there.  Beautiful.</td>', 'I feel like I''m right there.  Beautiful.', '2009-11-28 20:02:32.000000', NULL, 1),
(5744912, 835068, 90474, '<td valign="top">A little too saturated for my tastes, but good composition and capture.</td>', 'A little too saturated for my tastes, but good composition and capture.', '2009-11-28 20:41:30.000000', NULL, 1),
(5744915, 834828, 90474, '<td valign="top">The low viewpoint is usually a good idea; however, in this case, it gives up almost half of the frame to an uninteresting subject at the expense of a dramatic sky.  About half that much foreground would have made a better shot.</td>', 'The low viewpoint is usually a good idea; however, in this case, it gives up almost half of the frame to an uninteresting subject at the expense of a dramatic sky.  About half that much foreground would have made a better shot.', '2009-11-28 20:58:21.000000', NULL, 1),
