INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5746404, 834970, 68504, '<td valign="top">What is a little banding in a picture that dares and delivers as much as this one: shadowy foreground, flame sunshaft, misty grey back trees.</td>', 'What is a little banding in a picture that dares and delivers as much as this one: shadowy foreground, flame sunshaft, misty grey back trees.', '2009-11-30 01:20:49.000000', NULL, 0),
(5746406, 835101, 50034, '<td valign="top">Thanks, TrevyTrev (and everyone else who wrote encouraging words about this photo!)<br/> <br/>I knew when I posted it that it would probably be at least near the bottom, but I did it because it was an experiment that worked.<br/> <br/><i>I was thrilled that the watercolor effect could be achieved naturally, and without Photo Shop!</i> <br/> <br/>I am first of all an Artist!  Often, a Brownie must be reinterpreted as a Blue Ribbon for ART!<br/> <br/>Sharpness is well and good in its place, but the World of ART is truly blessed by those of us who ask, <b>"What''s a Box?"</b>  ;)</td>', 'Thanks, TrevyTrev (and everyone else who wrote encouraging words about this photo!) I knew when I posted it that it would probably be at least near the bottom, but I did it because it was an experiment that worked. I was thrilled that the watercolor effect could be achieved naturally, and without Photo Shop!  I am first of all an Artist!  Often, a Brownie must be reinterpreted as a Blue Ribbon for ART! Sharpness is well and good in its place, but the World of ART is truly blessed by those of us who ask, "What''s a Box?"  ;)', '2009-11-30 01:22:19.000000', NULL, 0),
(5746408, 834221, 68504, '<td valign="top">I thought this was mine.</td>', 'I thought this was mine.', '2009-11-30 01:24:59.000000', NULL, 0),
(5746411, 834683, 54033, '<td valign="top">Great shot, congratulations; definitely a superior shot and is worthy of the blue.  You other work is great too.</td>', 'Great shot, congratulations; definitely a superior shot and is worthy of the blue.  You other work is great too.', '2009-11-30 01:29:11.000000', NULL, 0),
