(5835719, 834683, 111123, '<td valign="top">Wow you take beautiful pictures. This picture is a 10!</td>', 'Wow you take beautiful pictures. This picture is a 10!', '2010-01-26 21:46:47.000000', NULL, 0),
(5945868, 834676, 98339, '<td valign="top">As you know this is one of my fav''s...I love it...such peace and beauty</td>', 'As you know this is one of my fav''s...I love it...such peace and beauty', '2010-04-14 11:10:01.000000', NULL, 0),
(6003392, 835009, 67258, '<td valign="top">A lovely tranquil landscape, with beautifully subtle colours.  Good work.</td>', 'A lovely tranquil landscape, with beautifully subtle colours.  Good work.', '2010-05-12 08:57:20.000000', NULL, 0),
(6116869, 834756, 119997, '<td valign="top">i like the centered composition as the balance between the right and left is more important than any rule of thirds. and in a field, the tree IS the center of attention. color is just a touch too exaggerated, but honestly? this is art, not simply another example of technical skill.</td>', 'i like the centered composition as the balance between the right and left is more important than any rule of thirds. and in a field, the tree IS the center of attention. color is just a touch too exaggerated, but honestly? this is art, not simply another example of technical skill.', '2010-08-04 05:36:58.000000', NULL, 0),
(6128990, 834765, 98339, '<td valign="top">really like the ominous feel of the clouds</td>', 'really like the ominous feel of the clouds', '2010-08-13 10:53:58.000000', NULL, 0),
(6172114, 834684, 96751, '<td valign="top">This is definitely an exceptional image.  Hard to say which is better - the color or the b/w.  Obviously, the b/w didn''t do too poorly for you :-)</td>', 'This is definitely an exceptional image.  Hard to say which is better - the color or the b/w.  Obviously, the b/w didn''t do too poorly for you :-)', '2010-09-26 21:03:59.000000', NULL, 0),
(6184814, 835083, 69008, '<td valign="top">This is cool, and kind of crazy at the same time, so I like it a lot. <br/> I think I see a speck of sensor dust in the lower left corner.  : )</td>', 'This is cool, and kind of crazy at the same time, so I like it a lot.  I think I see a speck of sensor dust in the lower left corner.  : )', '2010-10-07 15:26:43.000000', NULL, 0),
(6230662, 834612, 59267, '<td valign="top">Great shot! great composition and lighting!</td>', 'Great shot! great composition and lighting!', '2010-11-23 01:58:15.000000', NULL, 0),
(6293640, 834886, 63244, '<td valign="top">This is just beautiful, Kadi...well executed!</td>', 'This is just beautiful, Kadi...well executed!', '2011-01-25 12:39:18.000000', NULL, 0),
(6309831, 835130, 124815, '<td valign="top">Is this for real? Hope it won''t be affected by the warming stuff. Wow, so nice to look at it form the coziness of my studio! Thanks!</td>', 'Is this for real? Hope it won''t be affected by the warming stuff. Wow, so nice to look at it form the coziness of my studio! Thanks!', '2011-02-11 10:11:38.000000', NULL, 0),
(6429230, 834877, 38725, '<td valign="top">I wonder if the "greenish cast" that is mentioned is actually the moss and lichens growing on the side of the tower and buildings, a sight that may be unusual to folks from younger, drier places? Top Tor and Pil Tor area is one of my favourite dog walking spots and we often camp down at Cockingford Farm. Quintessential English countryside captured beautifully.</td>', 'I wonder if the "greenish cast" that is mentioned is actually the moss and lichens growing on the side of the tower and buildings, a sight that may be unusual to folks from younger, drier places? Top Tor and Pil Tor area is one of my favourite dog walking spots and we often camp down at Cockingford Farm. Quintessential English countryside captured beautifully.', '2011-05-31 09:50:36.000000', NULL, 0),
(6430956, 834612, 126371, '<td valign="top">Wow. I just ran across this shot. Excellent retainment of shadows etc... I just got a 10-22mm lens, so this is quite inspiring!</td>', 'Wow. I just ran across this shot. Excellent retainment of shadows etc... I just got a 10-22mm lens, so this is quite inspiring!', '2011-06-01 14:28:21.000000', NULL, 0),
(6956354, 835094, 11854, '<td valign="top">Funny how deceptive a photograph can be. I''d swear this is mountains with a lake in the front and storm clouds blowing in! Awesome!</td>', 'Funny how deceptive a photograph can be. I''d swear this is mountains with a lake in the front and storm clouds blowing in! Awesome!', '2013-01-13 13:47:58.000000', NULL, 0),
(6965132, 835094, 73828, '<td valign="top">Awesome!</td>', 'Awesome!', '2013-01-26 22:30:10.000000', NULL, 0);
